'use strict';

// Second-angle AP U.S. Government and Politics items. The builder supplies the
// shared q() normalizer so this file stays focused on authored item content.
// These are original, unreleased practice records; they are not College Board
// questions, source sets, or scoring materials.

module.exports = (q) => [
  // Unit 1: nine second-angle topic items plus nine depth items.
  q(1, '1.1', '1.A', 'A city charter states that government may exercise only powers that protect the natural rights of residents. Which idea is most directly expressed?', 'Natural rights place limits on legitimate government power.', ['Popular sovereignty requires every policy to be decided by a referendum.', 'Federalism gives local governments complete independence from constitutional limits.', 'Elite democracy requires policy to be made by a small group of experts.'], 'Natural-rights reasoning treats certain rights as prior to government and therefore as a basis for limiting public power.', { cognitiveProcess: 'connect', stimulus: 'The charter refers to life, liberty, and security as reasons for creating a local government.' }),
  q(1, '1.2', '1.B', 'A state uses elected legislators to make policy but also permits citizens to propose statutes by initiative. Which conclusion best describes the system?', 'It combines representative institutions with a participatory pathway.', ['It is exclusively an elite democracy because citizens never influence policy.', 'It is a direct monarchy because elected legislators retain authority.', 'It eliminates the need for political parties or organized interests.'], 'Representative democracy operates through elected officials, while initiatives add a direct participation mechanism without replacing the representative system.', { cognitiveProcess: 'compare' }),
  q(1, '1.3', '5.A', 'A national-security proposal would allow officials to search homes without warrants whenever they believe a threat might exist. Which constitutional concern is most directly raised?', 'The proposal could give government power that is not adequately limited by individual-rights protections.', ['The proposal would require equal representation in both chambers of Congress.', 'The proposal would transfer all reserved powers to state governments.', 'The proposal would make the Electoral College proportional in every state.'], 'The conflict is between a claimed public-safety objective and constitutional protections that constrain searches and executive discretion.', { cognitiveProcess: 'evaluate', stimulus: 'Supporters emphasize prevention; opponents argue that the standard provides no individualized judicial check.' }),
  q(1, '1.4', '1.B', 'Why did the Articles of Confederation make coordinated economic policy difficult?', 'Congress lacked effective authority to regulate interstate commerce and depended heavily on state cooperation.', ['Congress controlled a unified national tax system and permanent executive agencies.', 'The national judiciary could invalidate every state economic regulation.', 'The president could impose tariffs without legislative approval.'], 'The Confederation system left the national government dependent on states and gave it limited tools for coordinating trade and revenue policy.', { cognitiveProcess: 'explain' }),
  q(1, '1.5', '4.B', 'A Federalist pamphlet argues that the proposed Constitution would correct the weaknesses of the Articles, while an Anti-Federalist response warns about distant national power. Which analysis is strongest?', 'The sources identify a tradeoff between effective national authority and safeguards for state influence and liberty.', ['The sources prove that the two sides agreed about the proper scope of government.', 'The sources show that ratification involved no disagreement over institutional design.', 'The sources establish that the Articles created a stronger executive than the Constitution.'], 'The ratification debate included competing concerns about national capacity, state authority, representation, and individual liberty.', { cognitiveProcess: 'compare', stimulus: 'Source A favors a stronger union; Source B asks how citizens could control a large national government.' }),
  q(1, '1.6', '1.C', 'Which example most directly illustrates limited government?', 'A court rejects an executive action because the action exceeds authority granted by law and the Constitution.', ['A legislature gives an agency authority to administer a statute.', 'A citizen joins a political party to support a candidate.', 'A state uses a local referendum to approve a school budget.'], 'Limited government means public officials remain subject to constitutional and legal constraints, including judicial review of unlawful action.', { cognitiveProcess: 'apply' }),
  q(1, '1.7', '3.C', 'A state receives federal infrastructure funds and must meet federal reporting standards to keep the funds. Which relationship is shown?', 'Intergovernmental policy can combine state implementation with national conditions.', ['The state has become a foreign government outside the federal system.', 'The federal government has abolished all state policymaking authority.', 'The condition demonstrates that the Tenth Amendment forbids all federal grants.'], 'Federalism often involves shared administration: states implement programs while the national government uses funding or rules to pursue national objectives.', { cognitiveProcess: 'interpret', stimulus: 'The state continues to select projects, but it must document safety compliance to receive reimbursement.' }),
  q(1, '1.8', '2.C', 'In Gibbons v. Ogden, the Supreme Court interpreted federal power over interstate navigation. Which federalism principle did the decision reinforce?', 'Congress may regulate interstate commerce when the activity crosses state boundaries.', ['States may veto any federal regulation of commerce within their borders.', 'The president may rewrite the Commerce Clause through executive order.', 'The Court may regulate commerce directly without a law or dispute.'], 'Gibbons treated interstate navigation as commerce among the states and supported national authority under the Commerce Clause.', { cognitiveProcess: 'connect' }),
  q(1, '1.9', '5.B', 'Congress threatens to withhold a small portion of highway funding unless states adopt a minimum drinking age. Which feature of federalism is illustrated?', 'The national government is using a conditional grant to influence state policy.', ['The national government is exercising exclusive control over every state police power.', 'The state is using an executive agreement to bind foreign governments.', 'The Supreme Court is applying selective incorporation to a funding dispute.'], 'Conditional grants give states resources while attaching policy requirements, creating leverage without converting every state program into a federal program.', { cognitiveProcess: 'apply' }),
  q(1, '1.1', '4.A', 'A passage says that people may alter or abolish a government that consistently violates their rights. Which founding principle does the passage support?', 'Popular sovereignty and the consent of the governed', ['Judicial supremacy and lifetime judicial appointments', 'Administrative discretion and agency expertise', 'Equal state representation in the Senate'], 'The claim locates political legitimacy in the people and treats government as accountable to those whose rights it is supposed to secure.', { cognitiveProcess: 'analyze', stimulus: 'The passage describes government as an instrument created by the people rather than as an inherited authority.' }),
  q(1, '1.2', '1.E', 'A city council invites residents to deliberate on neighborhood priorities, but elected officials make the final decision. Which model is most evident?', 'Participatory democracy operating within a representative system', ['Elite democracy with no opportunity for citizen input', 'Direct democracy in which every resident votes on every law', 'Judicial democracy in which courts set the city budget'], 'Participation can shape agendas and recommendations even when representative officials retain formal decision-making authority.', { cognitiveProcess: 'classify' }),
  q(1, '1.3', '4.B', 'Which contrast between Federalist No. 10 and Brutus No. 1 is most accurate?', 'Federalist No. 10 emphasizes controlling factions through an extended republic, while Brutus warns that a large republic may threaten self-government.', ['Federalist No. 10 rejects representation, while Brutus supports direct democracy in every matter.', 'Both sources argue that state governments should be eliminated from the constitutional system.', 'Both sources claim that a large republic guarantees agreement among citizens.'], 'The documents offer different assessments of size, representation, faction, and the risk of centralized authority.', { cognitiveProcess: 'compare', stimulus: 'One source emphasizes the difficulty of forming a majority faction; the other emphasizes distance between representatives and citizens.' }),
  q(1, '1.4', '3.A', 'A table shows that the Confederation Congress requested funds from states but received less than half of the amount requested in each of three years. What conclusion is best supported?', 'The national government faced a recurring fiscal weakness because it depended on voluntary state contributions.', ['The table proves that the national government had unlimited taxing authority.', 'The table shows that states were required to surrender all revenue to Congress.', 'The table demonstrates that the national judiciary controlled appropriations.'], 'The repeated gap between requests and receipts supports a conclusion about dependence on state cooperation, not a claim about every aspect of the Confederation system.', { cognitiveProcess: 'interpret', stimulus: 'Year 1: requested 100, received 46. Year 2: requested 100, received 41. Year 3: requested 100, received 48.' }),
  q(1, '1.5', '1.D', 'Why did the Constitution include a process for ratification by conventions rather than relying only on state legislatures?', 'Convention ratification could appeal directly to the people and address concerns about whether the new system rested on popular consent.', ['Convention ratification guaranteed that every state would have identical population sizes.', 'Convention ratification allowed the president to approve the Constitution alone.', 'Convention ratification prevented citizens from debating the proposed system.'], 'Ratification conventions connected the new constitutional order to popular sovereignty and created a forum for public debate over the proposed structure.', { cognitiveProcess: 'explain' }),
  q(1, '1.6', '1.B', 'A law is enacted by Congress, signed by the president, and later invalidated by the Supreme Court. Which principle is most directly illustrated by the sequence?', 'Checks and balances allow different branches to participate in and constrain lawmaking.', ['The sequence proves that the executive branch is superior to the legislature.', 'The sequence shows that courts can initiate any policy without a case.', 'The sequence demonstrates that states control the federal judiciary.'], 'The sequence shows separate branches exercising distinct powers that can limit one another within the constitutional system.', { cognitiveProcess: 'apply' }),
  q(1, '1.7', '1.E', 'Which example best illustrates a concurrent power in the federal system?', 'Both the national government and the states levy taxes within their lawful authority.', ['Only the national government conducts diplomacy with foreign countries.', 'Only state governments establish local school districts.', 'Only the Supreme Court may review the constitutionality of a statute.'], 'Concurrent powers are shared by the national and state governments, while diplomacy is national and school administration is primarily state or local.', { cognitiveProcess: 'classify' }),
  q(1, '1.8', '2.D', 'In United States v. Lopez, the Supreme Court limited Congress power under the Commerce Clause. Which reasoning move is reflected?', 'The Court distinguished an activity with an insufficient connection to interstate commerce from activities Congress may regulate.', ['The Court held that Congress may regulate every local activity without a connection to commerce.', 'The Court transferred the power to declare war from Congress to the states.', 'The Court ruled that the Necessary and Proper Clause applies only to state legislatures.'], 'Lopez illustrates that the Commerce Clause has judicially enforceable boundaries and does not automatically reach every local activity.', { cognitiveProcess: 'connect' }),
  q(1, '1.9', '3.D', 'A map shows that states receiving a larger share of federal transportation grants also report more projects subject to federal accessibility rules. Which inference is most defensible?', 'Federal funding may create implementation incentives, but the map alone does not establish that funding caused every rule-compliant project.', ['The map proves that federal grants eliminate state discretion in all transportation decisions.', 'The map proves that states receiving fewer grants have no accessibility requirements.', 'The map shows that federalism prevents any national standards from applying to states.'], 'The pattern is consistent with grant conditions influencing implementation, but a map without controls cannot establish a complete causal explanation.', { cognitiveProcess: 'evaluate', stimulus: 'The map compares grant amounts and reported projects across states in one fiscal year.' }),

  // Unit 2: fifteen second-angle topic items plus fifteen depth items.
  q(2, '2.1', '1.C', 'Why does the Senate generally provide each state with equal representation while the House uses population-based districts?', 'The constitutional design balances state equality in the Senate with population-based representation in the House.', ['The design gives the president control over both chambers.', 'The design requires every state to elect the same number of House members.', 'The design eliminates the need for committees in either chamber.'], 'Bicameral representation was a constitutional compromise between equal state representation and representation tied to population.', { cognitiveProcess: 'explain' }),
  q(2, '2.2', '1.B', 'Which congressional action most directly demonstrates the power of the purse?', 'Congress refuses to appropriate funds for an executive proposal.', ['The Supreme Court grants certiorari in a case about the proposal.', 'The president issues a statement supporting the proposal.', 'A state governor appoints an agency director.'], 'Congress controls appropriations and can use funding decisions to influence executive implementation, subject to constitutional limits.', { cognitiveProcess: 'apply' }),
  q(2, '2.3', '3.C', 'A representative votes for a bill despite a majority of constituents opposing it, explaining that the bill serves the national interest. Which representation style is most evident?', 'The trustee model of representation', ['The delegate model of representation', 'The judicial-review model of representation', 'The bureaucratic model of representation'], 'A trustee uses personal judgment about the broader interest rather than treating current constituent opinion as the only guide.', { cognitiveProcess: 'classify' }),
  q(2, '2.4', '1.D', 'Which presidential action most clearly reflects the role of commander in chief?', 'Directing military operations after Congress has provided legal authorization and funding', ['Presiding over a state legislative committee', 'Deciding the constitutionality of a federal statute', 'Counting electoral votes without congressional procedure'], 'The commander-in-chief role concerns leadership of the armed forces, while Congress retains important powers over authorization and funding.', { cognitiveProcess: 'apply' }),
  q(2, '2.5', '1.E', 'The House votes to impeach a federal official and the Senate conducts a trial. What constitutional check is illustrated?', 'Congress can use impeachment and conviction procedures to hold federal officials accountable.', ['The president can remove a justice solely because of disagreement with an opinion.', 'A federal agency can amend the Constitution by regulation.', 'The Supreme Court can appoint members of Congress.'], 'Impeachment is a legislative check involving accusation by the House and trial by the Senate, with constitutional requirements for conviction.', { cognitiveProcess: 'explain' }),
  q(2, '2.6', '5.A', 'A president directs agencies to prioritize enforcement of an existing statute in a particular way, and critics argue that the direction changes the statute. What issue is raised?', 'The boundary between presidential implementation discretion and the duty to faithfully execute the law', ['The boundary between state taxation and foreign diplomacy', 'The boundary between jury service and congressional apportionment', 'The boundary between political parties and private schools'], 'Expansion of presidential power often raises questions about how much discretion the executive may exercise while implementing legislation.', { cognitiveProcess: 'evaluate', stimulus: 'The statute sets a broad policy goal but does not specify every enforcement priority.' }),
  q(2, '2.7', '4.A', 'A president repeats a short phrase in speeches until journalists and legislators use the phrase to describe the policy debate. Which effect is most directly illustrated?', 'Presidential communication can frame an issue and shape the public agenda.', ['Presidential communication automatically creates a constitutional amendment.', 'Presidential communication replaces Congress in appropriating funds.', 'Presidential communication gives courts authority to conduct elections.'], 'Presidential rhetoric can influence how citizens and institutions understand an issue even when it does not itself create legal authority.', { cognitiveProcess: 'analyze', stimulus: 'The phrase emphasizes responsibility and security rather than the technical details of the bill.' }),
  q(2, '2.8', '2.A', 'Why can life tenure for federal judges support judicial independence?', 'It reduces the threat that a judge will lose office because of an unpopular ruling, while impeachment remains available for serious misconduct.', ['It permits judges to write legislation without review.', 'It requires judges to win reelection after every decision.', 'It prevents Congress from creating any lower federal court.'], 'Tenure during good behavior insulates judges from ordinary electoral retaliation while preserving constitutional accountability mechanisms.', { cognitiveProcess: 'explain' }),
  q(2, '2.9', '2.B', 'A court follows the reasoning of an earlier decision when deciding a similar constitutional question. Which judicial principle is most directly involved?', 'Stare decisis, or respect for precedent', ['Executive privilege', 'Senatorial courtesy', 'Federal preemption'], 'Stare decisis promotes consistency by asking courts to consider prior decisions, although precedent can be distinguished, limited, or overruled.', { cognitiveProcess: 'identify' }),
  q(2, '2.10', '2.C', 'After hearing oral arguments, the Supreme Court assigns a justice to write the majority opinion. What does the assignment signal?', 'A majority of the justices agreed on the judgment and will develop the reasoning for the Court decision.', ['The president has vetoed the case before the opinion is published.', 'The case will automatically be returned to the state legislature.', 'The justice writing the opinion can decide the case without other votes.'], 'The majority opinion explains the judgment supported by a majority; the assignment begins the process of developing reasoning that other justices may join or revise.', { cognitiveProcess: 'connect' }),
  q(2, '2.11', '2.D', 'Which congressional action is a constitutional check on the federal judiciary that does not direct the outcome of a pending case?', 'Congress can create and organize lower federal courts within constitutional limits.', ['Congress can order a justice to change a vote in a pending case.', 'Congress can cancel a judicial opinion through a simple press release.', 'Congress can replace a jury verdict with a presidential order.'], 'Congress has institutional authority over lower-court structure, but separation of powers limits direct control over particular judicial decisions.', { cognitiveProcess: 'apply' }),
  q(2, '2.12', '1.A', 'An agency receives a statute instructing it to administer a food-safety program. Which bureaucratic function is illustrated when the agency inspects facilities?', 'Implementation and enforcement of a law passed through the political process', ['Ratification of a constitutional amendment', 'Selection of senators through primary elections', 'Judicial review of every state constitution'], 'Bureaucracies implement statutes through administration, inspection, service delivery, enforcement, and other specialized work.', { cognitiveProcess: 'identify' }),
  q(2, '2.13', '1.E', 'An agency writes detailed safety standards after Congress delegates authority in a broad statute. Which authority is the agency using?', 'Rulemaking authority delegated by Congress', ['The power to conduct impeachment trials', 'The power to ratify treaties', 'The power to appoint Supreme Court justices'], 'Delegated rulemaking lets agencies translate broad statutory goals into more specific, enforceable regulations within legal limits.', { cognitiveProcess: 'apply' }),
  q(2, '2.14', '4.C', 'A congressional committee requests agency records, holds a hearing, and asks why a program missed its performance target. Which tool is being used?', 'Legislative oversight', ['Judicial incorporation', 'Presidential succession', 'Constitutional ratification'], 'Oversight allows Congress to monitor administration, investigate implementation, and use hearings or appropriations to influence agencies.', { cognitiveProcess: 'identify', stimulus: 'The committee asks the agency director to explain the data and describe corrective action.' }),
  q(2, '2.15', '5.B', 'When different branches support different approaches to an environmental policy, what most directly affects the final outcome?', 'The constitutional powers, institutional incentives, and bargaining strategies of the branches involved', ['The assumption that one branch always controls every policy area', 'The requirement that courts write every administrative rule', 'The absence of any role for organized interests or public opinion'], 'Policy emerges through interaction among branches, agencies, courts, interests, and public pressures rather than through a single institutional command.', { cognitiveProcess: 'argue' }),
  q(2, '2.1', '3.B', 'A table shows that House reelection rates remain high while Senate reelection rates fluctuate more across four election cycles. Which explanation is most plausible?', 'Senate races cover statewide constituencies and may be more exposed to national political swings than House races.', ['Senators are appointed by governors in every election cycle.', 'House members cannot face primary challenges under the Constitution.', 'The Senate has no party organizations or campaign fundraising.'], 'The pattern is consistent with differences in constituency size, campaign context, and nationalization, although the table alone cannot prove one cause.', { cognitiveProcess: 'interpret', stimulus: 'House reelection: 91%, 90%, 92%, 91%. Senate reelection: 78%, 86%, 74%, 88%.' }),
  q(2, '2.2', '1.C', 'Which congressional structure gives committees an important role in developing legislation?', 'Committees can hold hearings, revise bills, and decide which proposals receive detailed consideration.', ['Committees are required to approve every judicial opinion.', 'Committees replace elections with agency appointments.', 'Committees allow the president to write all statutes without a vote.'], 'The committee system specializes legislative work and filters proposals before full-chamber debate and voting.', { cognitiveProcess: 'explain' }),
  q(2, '2.3', '5.C', 'A roll-call chart shows members of one party voting together more often on high-profile bills than on routine bills. Which conclusion is best supported?', 'Party cohesion varies by issue salience and legislative context.', ['Party labels determine every vote without exception.', 'The chart proves that constituents never influence legislators.', 'High-profile bills cannot involve ideological disagreement.'], 'The chart supports a conditional pattern rather than an absolute claim about congressional behavior.', { cognitiveProcess: 'evaluate', stimulus: 'Party cohesion is 84% on high-profile bills and 61% on routine bills in the measured session.' }),
  q(2, '2.4', '1.D', 'Why might a president use an executive agreement instead of seeking a treaty?', 'An executive agreement can establish an international commitment without requiring the same Senate treaty-ratification process.', ['An executive agreement permanently changes the Constitution.', 'An executive agreement gives state courts control over foreign policy.', 'An executive agreement must be approved by every local government.'], 'Executive agreements are a presidential tool in foreign affairs, but their scope and durability remain subject to legal and political constraints.', { cognitiveProcess: 'compare' }),
  q(2, '2.5', '5.B', 'Congress passes a bill over a presidential veto with the required supermajority. What does the outcome demonstrate?', 'A formal legislative check can overcome presidential opposition when the constitutional threshold is met.', ['The president has no role in the legislative process.', 'The Supreme Court must approve every veto override.', 'The states have repealed the separation of powers.'], 'The override illustrates that the veto is a check, not an absolute presidential power, because the Constitution provides a congressional response.', { cognitiveProcess: 'apply' }),
  q(2, '2.6', '2.D', 'A federal court blocks a presidential directive because it conflicts with a statute enacted by Congress. Which limit on expanded presidential power is shown?', 'Presidential action remains subject to statutory and constitutional review.', ['Presidential directives cannot ever be reviewed by courts.', 'The court has transferred all executive authority to Congress.', 'The directive automatically becomes a treaty after judicial review.'], 'Courts may evaluate executive action against the Constitution and statutes, especially when a directive exceeds delegated authority.', { cognitiveProcess: 'connect' }),
  q(2, '2.7', '4.B', 'A televised address emphasizes a policy threat but omits data that complicate the claim. Which source-analysis question should a student ask first?', 'How do the speaker, purpose, selected evidence, and intended audience shape the message?', ['Whether the speaker has authority to appoint every judge in the country', 'Whether television coverage automatically makes the claim accurate', 'Whether Congress is prohibited from debating the policy'], 'Source analysis evaluates perspective and purpose as well as the evidence included and omitted in a public communication.', { cognitiveProcess: 'analyze', stimulus: 'The address is delivered during a debate over a proposed national policy.' }),
  q(2, '2.8', '1.C', 'Why can the appointment process create tension over the federal judiciary?', 'The elected branches select judges, but lifetime tenure allows judges to exercise independent constitutional judgment after confirmation.', ['Judges are required to campaign for office after confirmation.', 'The judiciary writes the party platforms for Congress.', 'The appointment process prevents courts from hearing constitutional cases.'], 'The process connects courts to elected institutions while tenure protects judicial independence, creating debate over qualifications and interpretive direction.', { cognitiveProcess: 'explain' }),
  q(2, '2.9', '2.B', 'Which action best illustrates judicial restraint?', 'A court upholds a law when it finds a reasonable constitutional basis and declines to replace legislative policy judgment.', ['A court invalidates every law it dislikes without constitutional reasoning.', 'A court writes a complete administrative code for Congress.', 'A court requires all voters to adopt one policy position.'], 'Judicial restraint emphasizes deference to elected branches when constitutional text and precedent do not require intervention.', { cognitiveProcess: 'classify' }),
  q(2, '2.10', '2.A', 'Why might the Supreme Court use a narrow holding rather than deciding every issue raised by the parties?', 'A narrow holding resolves the case while limiting unnecessary constitutional or doctrinal consequences.', ['A narrow holding prevents the parties from receiving any judgment.', 'A narrow holding allows Congress to select the justices voting in the case.', 'A narrow holding means the Court has no power of judicial review.'], 'Courts often limit decisions to the facts and legal question necessary to resolve a dispute, which can preserve flexibility for later cases.', { cognitiveProcess: 'explain' }),
  q(2, '2.11', '1.E', 'Which action can the Senate take as part of its constitutional role involving the federal judiciary?', 'Provide advice and consent on presidential nominations to federal courts.', ['Write the majority opinion in every Supreme Court case', 'Remove a justice through an ordinary appropriations bill', 'Direct a lower court to ignore a constitutional precedent'], 'The Senate confirmation role checks presidential appointments while leaving judges responsible for deciding cases under law.', { cognitiveProcess: 'identify' }),
  q(2, '2.12', '3.A', 'An agency report shows that two regional offices applied the same statute differently before receiving new guidance. What bureaucratic issue is suggested?', 'Implementation discretion can produce variation unless agencies establish consistent rules or supervision.', ['The data prove that Congress cannot pass statutes.', 'The variation shows that courts administer every agency program.', 'The report proves that all agency employees are elected.'], 'Agencies often exercise discretion in applying broad statutes, so guidance, oversight, and review can affect consistency.', { cognitiveProcess: 'interpret', stimulus: 'Before guidance, approval rates were 42% in Region A and 68% in Region B; after guidance, both were near 55%.' }),
  q(2, '2.13', '4.C', 'An agency publishes a proposed regulation, receives public comments, and revises the final rule. Which process is most directly described?', 'Notice-and-comment rulemaking', ['Senate cloture', 'Judicial impeachment', 'Electoral reapportionment'], 'Notice-and-comment procedures give affected parties an opportunity to provide information and objections before a final administrative rule.', { cognitiveProcess: 'identify' }),
  q(2, '2.14', '1.E', 'Which action is most likely to improve bureaucratic accountability without eliminating agency expertise?', 'Congress can require reporting, conduct oversight, and review whether the agency is implementing its statutory mandate.', ['Congress can permit the agency to ignore all statutory limits.', 'Congress can require courts to approve every routine employee decision.', 'Congress can prohibit citizens from challenging agency action.'], 'Accountability tools can monitor agencies while preserving specialized administration within the boundaries established by law.', { cognitiveProcess: 'evaluate' }),
  q(2, '2.15', '3.F', 'A policy becomes law after the president negotiates with congressional leaders, agencies propose implementation rules, and a court resolves a challenge. What conclusion is best supported?', 'Policymaking can be an interbranch process that extends beyond the passage of a statute.', ['Only Congress participates in policy after a bill is introduced.', 'Courts and agencies cannot affect the meaning or implementation of policy.', 'The president can eliminate all legislative and judicial checks through negotiation.'], 'The sequence illustrates how institutions with different powers influence policy design, implementation, and constitutional interpretation.', { cognitiveProcess: 'synthesize', stimulus: 'The final rule differs from the original bill, and the court upholds some provisions while remanding others.' }),

  // Unit 3: thirteen second-angle topic items plus two depth items.
  q(3, '3.1', '1.B', 'What is the primary purpose of the Bill of Rights in the constitutional system?', 'It lists protections that limit government interference with individual liberties.', ['It guarantees that every policy will receive unanimous public support.', 'It gives state governments exclusive authority over foreign affairs.', 'It establishes political parties as constitutional branches.'], 'The Bill of Rights identifies important liberties and procedural protections against government action, although rights can involve constitutional balancing.', { cognitiveProcess: 'identify' }),
  q(3, '3.2', '2.B', 'A public school requires students to participate in a teacher-led prayer. Which constitutional principle is most directly implicated?', 'The Establishment Clause limits government sponsorship of religious exercise.', ['The Commerce Clause requires schools to regulate interstate trade.', 'The Appointments Clause gives students power to select teachers.', 'The Equal Protection Clause eliminates all distinctions between public and private conduct.'], 'Government-sponsored prayer raises an Establishment Clause question because public officials are directing or endorsing religious exercise.', { cognitiveProcess: 'apply' }),
  q(3, '3.3', '2.C', 'A student wears a silent armband to protest a school policy, and the school punishes the student without evidence of disruption. Which case is most relevant?', 'Tinker v. Des Moines', ['McCulloch v. Maryland', 'United States v. Lopez', 'Gideon v. Wainwright'], 'Tinker protects student symbolic speech when the expression is not materially and substantially disruptive to school operations.', { cognitiveProcess: 'connect' }),
  q(3, '3.4', '2.D', 'A newspaper is prevented from publishing a story solely because officials fear that readers may react negatively. Which constitutional issue is raised?', 'Prior restraint on freedom of the press', ['Equal representation in the Senate', 'The right of Congress to tax income', 'The president power to negotiate treaties'], 'A government order stopping publication before it occurs is a prior-restraint issue and receives especially serious constitutional scrutiny.', { cognitiveProcess: 'apply' }),
  q(3, '3.5', '2.A', 'Which principle did District of Columbia v. Heller recognize?', 'The Second Amendment protects an individual right to possess a firearm for lawful purposes such as self-defense, subject to constitutional analysis of regulation.', ['The Second Amendment applies only to state legislatures and not individuals.', 'The Second Amendment prevents every form of firearm regulation.', 'The Second Amendment gives Congress power to appoint local police chiefs.'], 'Heller recognized an individual right while also explaining that the decision did not make every regulation invalid.', { cognitiveProcess: 'connect' }),
  q(3, '3.6', '5.A', 'A city limits amplified demonstrations near a hospital to certain hours and applies the rule to all viewpoints. Which analysis is strongest?', 'The rule may be a content-neutral time, place, and manner regulation if it leaves adequate alternative channels and serves a legitimate interest.', ['The rule is automatically invalid because speech can never be regulated in public.', 'The rule is automatically valid because public safety overrides every constitutional protection.', 'The rule is a treaty because it applies to an international organization.'], 'Speech protections can coexist with neutral regulations designed to address public safety, traffic, or access, but the regulation must satisfy constitutional standards.', { cognitiveProcess: 'evaluate' }),
  q(3, '3.7', '2.C', 'What does selective incorporation mean?', 'The Supreme Court has applied many Bill of Rights protections to the states through the Fourteenth Amendment.', ['Every provision of every state constitution automatically applies to Congress.', 'The president chooses which rights state courts must enforce.', 'The Bill of Rights applies only to federal agencies and never to states.'], 'Selective incorporation is the process through which the Court has recognized particular fundamental rights as binding on state governments through the Fourteenth Amendment.', { cognitiveProcess: 'identify' }),
  q(3, '3.8', '2.D', 'Which principle from Gideon v. Wainwright is most directly relevant when a state denies counsel to an indigent felony defendant?', 'The right to appointed counsel in serious criminal cases is fundamental and applies to the states.', ['The right to counsel applies only in civil disputes over property.', 'States may deny counsel whenever a defendant is unable to pay.', 'The case established that Congress may regulate all local elections.'], 'Gideon held that the Sixth Amendment right to counsel is fundamental and incorporated against the states in serious criminal prosecutions.', { cognitiveProcess: 'connect' }),
  q(3, '3.9', '5.B', 'A state requires a warrant for a home search but permits officials to collect private medical information without a lawful basis. Which issue is most directly raised?', 'Substantive privacy and due-process limits on government intrusion into personal liberty', ['The issue is solely about equal state representation in Congress.', 'The issue concerns the president power to veto a bill.', 'The issue proves that all government records are public by default.'], 'Privacy analysis can involve substantive liberty interests and due-process limits even when the government claims an administrative purpose.', { cognitiveProcess: 'evaluate' }),
  q(3, '3.10', '4.A', 'A civil-rights organization uses litigation, boycotts, and public demonstrations to challenge an unequal school system. Which conclusion is most accurate?', 'Social movements can use multiple strategies to change public opinion, law, and institutional practice.', ['Social movements must rely only on presidential executive orders.', 'Litigation prevents citizens from using political participation.', 'A movement succeeds automatically whenever it files one lawsuit.'], 'Movements often combine legal, electoral, economic, organizational, and expressive strategies rather than relying on one institution.', { cognitiveProcess: 'analyze', stimulus: 'The organization seeks a court order while also building a coalition of families and local businesses.' }),
  q(3, '3.11', '1.E', 'Congress passes a law prohibiting discrimination in public accommodations after sustained activism. Which government response is illustrated?', 'Civil-rights legislation using national authority to address unequal treatment.', ['A state has withdrawn from the federal system.', 'The Supreme Court has replaced Congress as a lawmaking body.', 'The law demonstrates that social movements cannot affect policy.'], 'Government responses to social movements can include legislation that establishes rights or prohibits discriminatory practices.', { cognitiveProcess: 'apply' }),
  q(3, '3.12', '5.C', 'A majority supports a policy that would prohibit a small religious group from using a public forum under the same rules as other groups. Which constitutional concern is strongest?', 'Majority rule is limited when it denies a minority equal access to a protected public forum.', ['The majority may always remove minority rights through a simple vote.', 'Minority rights apply only when the minority is large enough to win an election.', 'The policy is automatically valid because public forums are never subject to constitutional rules.'], 'Representative democracy permits majority decision-making but constitutional rights constrain majorities from targeting protected minorities.', { cognitiveProcess: 'argue' }),
  q(3, '3.13', '5.D', 'A university considers a policy designed to expand opportunity for applicants from historically excluded groups. Which question is most important for constitutional analysis?', 'What classification the policy uses, what governmental interest it serves, and whether the means are appropriately related to that interest.', ['Whether every applicant will receive the same outcome regardless of qualifications or policy design.', 'Whether the policy can be adopted without any public explanation or review.', 'Whether affirmative action questions are decided by political parties rather than courts.'], 'Equal-protection analysis examines classifications, governmental interests, and the fit between the policy and its stated objective; a careful conclusion requires the policy details.', { cognitiveProcess: 'evaluate' }),
  q(3, '3.3', '2.C', 'A student newspaper publishes a political article, and school officials remove it because they disagree with its viewpoint even though the article causes no material disruption. Which principle is most relevant?', 'Viewpoint-based suppression of protected expression is constitutionally suspect.', ['The school may suppress any unpopular view without considering disruption.', 'The case concerns only the federal taxing power.', 'The First Amendment protects only speech written by government officials.'], 'The First Amendment is especially concerned when government selects a viewpoint for punishment rather than applying a neutral rule tied to a legitimate institutional need.', { cognitiveProcess: 'analyze' }),
  q(3, '3.8', '2.D', 'A defendant confesses after police question the defendant in custody without providing required warnings. Which constitutional protection is most directly implicated?', 'The Fifth Amendment privilege against self-incrimination as applied through Miranda safeguards', ['The Tenth Amendment reservation of powers to states', 'The Seventh Amendment right to a civil jury in every dispute', 'The Twenty-Sixth Amendment voting-age rule'], 'Miranda safeguards protect against compelled self-incrimination during custodial interrogation by requiring procedural warnings about important rights.', { cognitiveProcess: 'connect' }),

  // Unit 4: ten second-angle topic items plus two depth items.
  q(4, '4.1', '3.A', 'A national survey asks respondents whether government should expand services but does not define the services. What limitation should analysts note?', 'Responses may reflect different interpretations of the question rather than one shared policy preference.', ['The survey proves that all respondents hold identical ideological views.', 'The wording guarantees a representative sample regardless of selection.', 'The survey can measure voting turnout only and cannot measure attitudes.'], 'Ambiguous wording can reduce the interpretability of public-opinion results because respondents may answer different questions in their minds.', { cognitiveProcess: 'evaluate', stimulus: 'The survey reports support at 58 percent but provides no definition of the proposed services.' }),
  q(4, '4.2', '1.A', 'A person learns civic norms through family discussions, school lessons, peer groups, and media. Which concept is illustrated?', 'Political socialization', ['Judicial review', 'Federal preemption', 'Legislative apportionment'], 'Political socialization is the process through which people acquire political attitudes, values, identities, and habits from social influences.', { cognitiveProcess: 'identify' }),
  q(4, '4.3', '3.C', 'A survey finds that respondents increasingly describe themselves as independent while their policy positions remain close to one major party. Which conclusion is most defensible?', 'The label change may reflect changes in political identity without proving a complete ideological realignment.', ['The survey proves that party organizations no longer matter.', 'The data show that every respondent changed every policy position.', 'Independent identification automatically means no political preferences exist.'], 'Political labels and policy preferences do not always move together, so the survey supports a limited conclusion about identity rather than a total realignment.', { cognitiveProcess: 'interpret', stimulus: 'Independent identification rises from 28% to 36%, while issue positions change only modestly.' }),
  q(4, '4.4', '4.B', 'After a major economic crisis, a poll shows increased support for government regulation. Which explanation is most reasonable?', 'Political events can change which problems citizens prioritize and how they evaluate government action.', ['A single event proves that every citizen adopted the same ideology.', 'The poll proves that political socialization ends after adulthood.', 'The result shows that public opinion cannot change over time.'], 'Events can influence issue salience and attitudes, but a poll alone does not show that the event was the only cause.', { cognitiveProcess: 'explain', stimulus: 'Support for stronger financial regulation rises from 44% before the crisis to 57% afterward.' }),
  q(4, '4.5', '3.B', 'A probability sample estimates support at 51 percent with a margin of error of plus or minus 3 percentage points. Which range is consistent with the estimate?', 'Approximately 48 percent to 54 percent', ['Exactly 51 percent for every member of the population', 'Approximately 3 percent to 51 percent', 'A range from 51 percent to 100 percent'], 'A margin of error describes a range around the estimate under stated sampling assumptions; it does not guarantee the exact population value.', { cognitiveProcess: 'calculate', stimulus: 'Estimate: 51%; margin of error: +/- 3 percentage points.' }),
  q(4, '4.6', '3.F', 'A poll reports very high support after asking, "Do you support the fair and responsible reform that experts recommend?" What limitation is most apparent?', 'The leading wording may influence respondents and bias the measured support estimate.', ['The question is automatically unbiased because it mentions experts.', 'The wording proves that the sample was selected randomly.', 'The poll cannot measure any attitude because all questions use words.'], 'Loaded terms such as fair, responsible, and experts can encourage a preferred response and make the result less valid as a measure of neutral opinion.', { cognitiveProcess: 'evaluate' }),
  q(4, '4.7', '1.E', 'A party platform supports lower taxes, reduced regulation, and greater state authority on several social issues. Which analysis is most accurate?', 'The platform reflects broad conservative tendencies, although individual candidates and coalitions may vary by issue.', ['The platform proves that every party member holds the same view.', 'The platform is a constitutional document that courts must enforce.', 'The platform shows that ideology has no relationship to policy.'], 'Party platforms often express broad ideological tendencies without determining every position of every candidate or voter.', { cognitiveProcess: 'classify' }),
  q(4, '4.8', '5.C', 'A policymaker argues that a national standard is justified because pollution crosses state boundaries. Which evidence would best support the argument?', 'Evidence that the problem crosses jurisdictions and that national authority could coordinate a more effective response.', ['A claim that all state policies are identical in every region.', 'A single personal preference with no description of the problem.', 'A statement that ideology eliminates the need for constitutional authority.'], 'A strong ideological and policy argument links the preferred governmental response to the scope of the problem, constitutional authority, and expected consequences.', { cognitiveProcess: 'argue' }),
  q(4, '4.9', '1.D', 'Congress increases infrastructure spending during an economic slowdown. Which policy tool is being used?', 'Fiscal policy through government spending', ['Monetary policy through a central-bank interest-rate decision', 'Judicial review through a constitutional holding', 'Political socialization through family discussion'], 'Fiscal policy uses taxing and spending decisions, while monetary policy is conducted by the Federal Reserve through tools such as interest rates and money supply.', { cognitiveProcess: 'compare' }),
  q(4, '4.10', '5.B', 'A debate compares a proposal for national health assistance with a proposal that gives states more discretion over assistance design. Which ideological question is central?', 'How much responsibility and authority should the national government exercise in social policy?', ['Whether Congress should have equal state representation in the Senate', 'Whether courts may hear cases involving federal statutes', 'Whether political parties can recruit candidates for office'], 'Social-policy ideology often involves competing views about government responsibility, individual choice, equality, and the appropriate level of policymaking.', { cognitiveProcess: 'explain' }),
  q(4, '4.5', '3.D', 'A survey shows support for a policy at 62 percent among respondents contacted by text message and 49 percent among respondents contacted by landline. Which conclusion is best supported?', 'The two contact groups report different levels of support, but the difference may reflect sampling or population-composition differences.', ['The contact method proves that one group is more informed.', 'The data establish that the policy will pass in Congress.', 'The difference proves that every respondent changed views because of the survey.'], 'Comparing subgroup estimates can reveal a pattern, but the data alone do not identify why the groups differ or predict a policy outcome.', { cognitiveProcess: 'interpret', stimulus: 'Text group: n=600, support 62%. Landline group: n=400, support 49%.' }),
  q(4, '4.6', '3.E', 'A researcher finds that people who watch more campaign news are also more likely to report high political knowledge. Which caution is most appropriate?', 'The association does not by itself establish that watching campaign news caused the higher knowledge.', ['The association proves that news has no political effect.', 'The study proves that all viewers receive identical information.', 'The relationship cannot be discussed because survey data are never useful.'], 'Correlation can be consistent with several explanations, including reverse causation or prior interest, so causal claims require stronger evidence.', { cognitiveProcess: 'evaluate' }),

  // Unit 5: thirteen second-angle topic items plus twelve depth items.
  q(5, '5.1', '1.D', 'A voter chooses a candidate after comparing the candidates stated plans for the next term. Which voting model is illustrated?', 'Prospective voting', ['Retrospective voting', 'Straight-ticket voting', 'Randomized judicial review'], 'Prospective voting evaluates expected future performance or policy rather than primarily judging the incumbent record.', { cognitiveProcess: 'classify' }),
  q(5, '5.2', '3.B', 'A county reports lower turnout in local elections than in presidential elections, even though the same residents are eligible. Which factor is a plausible explanation?', 'Local elections may receive less media attention and mobilization, and voters may perceive lower stakes.', ['Local elections are always unconstitutional for eligible voters.', 'Presidential elections eliminate all registration requirements.', 'Turnout is determined only by the number of candidates on the ballot.'], 'Election timing, perceived importance, campaign mobilization, information, and registration rules can all affect turnout.', { cognitiveProcess: 'explain', stimulus: 'Turnout is 62% in presidential elections and 31% in comparable local elections.' }),
  q(5, '5.3', '1.A', 'A political party recruits candidates, publishes a platform, and organizes legislators after an election. Which party function is most directly shown?', 'Linking voters to government and organizing governing institutions', ['Replacing the judiciary with a party tribunal', 'Preventing citizens from learning policy positions', 'Serving only as a temporary census agency'], 'Parties connect citizens and institutions through recruitment, policy aggregation, mobilization, and legislative organization.', { cognitiveProcess: 'identify' }),
  q(5, '5.4', '4.A', 'A party changes its platform after a new group of voters becomes important in several competitive states. Which explanation is strongest?', 'The party is adapting its coalition and message to changing electoral incentives.', ['The party platform is a constitutional amendment that cannot change.', 'The change proves that voters no longer influence parties.', 'The party has eliminated the need for candidates or campaign organizations.'], 'Parties adapt to coalition changes, issue salience, demographic shifts, and electoral competition.', { cognitiveProcess: 'analyze', stimulus: 'Party leaders publicly debate whether a new policy position will attract voters without losing existing supporters.' }),
  q(5, '5.5', '1.E', 'Why can a third-party candidate affect an election without winning a large share of electoral votes?', 'The candidate may draw enough votes from one major-party coalition to change which candidate wins a plurality.', ['Third parties automatically receive one-half of every state electoral vote.', 'Third parties cannot appear on ballots unless they win the presidency first.', 'A third party can change the Constitution through a campaign advertisement.'], 'Plurality rules mean that a relatively small third-party vote share can alter the major-party distribution in a close contest.', { cognitiveProcess: 'explain' }),
  q(5, '5.6', '4.C', 'An interest group submits testimony to a legislative committee and provides technical research about a proposed regulation. Which strategy is illustrated?', 'Lobbying through information and direct communication with policymakers', ['Judicial appointment through senatorial confirmation', 'Electoral vote allocation by the Electoral College', 'Executive privilege over legislative records'], 'Lobbying includes communicating policy preferences, evidence, and expertise to officials who make or implement policy.', { cognitiveProcess: 'identify', stimulus: 'The group describes likely effects on small businesses and proposes specific amendments.' }),
  q(5, '5.7', '5.B', 'Why might people benefit from an interest group victory even if they never join or contribute to the group?', 'The policy may provide a public good whose benefits are difficult to withhold from nonmembers.', ['Interest groups can require every citizen to join under the Constitution.', 'A public good is available only to the organizations that paid for it.', 'Nonmembers automatically receive extra votes in the next election.'], 'Free-rider incentives arise when people can enjoy a policy benefit without bearing the costs of organizing or contributing.', { cognitiveProcess: 'explain' }),
  q(5, '5.8', '3.C', 'A candidate wins the statewide popular vote in a state that uses a winner-take-all allocation. What is the most likely electoral consequence?', 'The candidate receives the states electoral votes under that state rule, subject to the state law and constitutional process.', ['The candidate receives every electoral vote in the country.', 'The candidate is automatically elected before other states report results.', 'The candidate loses the state electoral votes because only Congress counts votes.'], 'Winner-take-all allocation links the statewide result to the state electoral-vote slate, while the national result depends on the total electoral vote process.', { cognitiveProcess: 'apply' }),
  q(5, '5.9', '3.A', 'A state legislature redraws congressional districts after a census. Which constitutional process is most directly involved?', 'Reapportionment and redistricting based on population changes', ['Treaty ratification by the Senate', 'Selective incorporation of the Bill of Rights', 'Judicial appointment by the president'], 'Census population data guide reapportionment among states and redistricting within states, subject to constitutional and statutory requirements.', { cognitiveProcess: 'identify' }),
  q(5, '5.10', '4.D', 'A campaign uses different messages for suburban parents, union members, and young voters after analyzing survey data. Which strategy is illustrated?', 'Targeted campaign communication', ['Judicial restraint', 'Federal preemption', 'Constitutional convention ratification'], 'Campaigns may use polling, voter files, consultants, and media platforms to tailor messages to different audiences.', { cognitiveProcess: 'analyze', stimulus: 'The campaign keeps the same broad policy but emphasizes different reasons for supporting it in each audience.' }),
  q(5, '5.11', '5.C', 'Why can disclosure rules be relevant to campaign-finance debates?', 'Disclosure can give voters information about who is funding political communication and may support accountability.', ['Disclosure rules guarantee that every advertisement is accurate.', 'Disclosure eliminates the constitutional distinction between speech and conduct.', 'Disclosure requires every donor to become a candidate for office.'], 'Disclosure can increase transparency, although it does not by itself resolve every question about regulation, privacy, or political expression.', { cognitiveProcess: 'explain' }),
  q(5, '5.13', '3.E', 'A study finds that users are more likely to see political posts similar to posts they previously engaged with. Which media condition is suggested?', 'Algorithmic or social filtering may contribute to selective exposure and echo-chamber effects.', ['All users are receiving the same politically neutral news stream.', 'The study proves that online content cannot affect political beliefs.', 'The finding means that traditional media no longer exist.'], 'Digital platforms can personalize exposure, which may increase relevant content while also narrowing the range of views a user encounters.', { cognitiveProcess: 'interpret', stimulus: 'The study compares feeds of users who previously engaged with different political topics.' }),
  q(5, '5.1', '5.A', 'A voter supports a candidate because the candidate belongs to the voters preferred party, even without reviewing the candidates current platform. Which influence is most evident?', 'Party identification as a voting cue', ['Judicial review of campaign finance', 'A conditional federal grant', 'A bureaucratic notice-and-comment rule'], 'Party identification can serve as a shortcut that helps voters make decisions when they have limited information or stable partisan attachments.', { cognitiveProcess: 'identify' }),
  q(5, '5.2', '3.D', 'A registration reform is followed by larger increases in turnout among newly eligible voters than among already registered voters. Which conclusion is best supported?', 'The reform is associated with greater participation among newly eligible voters, although other factors may also contribute.', ['The reform proves that registration is the only cause of turnout.', 'The reform shows that already registered voters are constitutionally barred from voting.', 'The data prove that every newly eligible voter voted because of the reform.'], 'The comparison supports an association and a subgroup difference but does not establish that the reform alone caused every change.', { cognitiveProcess: 'evaluate', stimulus: 'Newly eligible turnout rises from 24% to 39%; already registered turnout rises from 68% to 72%.' }),
  q(5, '5.3', '5.C', 'A party platform combines positions from labor advocates, business groups, and environmental voters. What challenge is the party attempting to manage?', 'Aggregating interests that may support the party but disagree about particular policies', ['Eliminating the need for a governing coalition', 'Replacing the Constitution with a private contract', 'Preventing any group from participating in elections'], 'Parties build coalitions by packaging multiple interests into a platform, which can require compromise among groups.', { cognitiveProcess: 'argue' }),
  q(5, '5.4', '3.C', 'Across three elections, a party gains support among college-educated voters but loses support among voters without college degrees. What does the pattern show?', 'The party coalition changed across the measured elections, but the data alone do not identify the cause.', ['Every voter in each education group changed parties.', 'The party no longer has any policy positions.', 'Education explains all voting behavior without other evidence.'], 'The data support a group-level shift in coalition support, not a claim about every individual or a complete causal explanation.', { cognitiveProcess: 'interpret', stimulus: 'College graduates: 45%, 51%, 56%. Non-college voters: 53%, 48%, 43%.' }),
  q(5, '5.5', '5.D', 'A third-party candidate advocates one issue that both major parties previously ignored, and both later address the issue. What possible effect is illustrated?', 'Third parties can influence the issue agenda even when they do not win office.', ['Third parties automatically receive the presidency when major parties adopt an issue.', 'Third parties can force the Supreme Court to write a platform.', 'Third parties eliminate plurality voting by making one demand.'], 'Third parties may introduce issues, pressure major parties, or alter debate even when electoral rules make winning office difficult.', { cognitiveProcess: 'argue' }),
  q(5, '5.6', '5.D', 'An interest group organizes a letter-writing campaign after providing members with a common message and contact information for legislators. Which strategy is shown?', 'Grassroots mobilization', ['Judicial impeachment', 'Presidential succession', 'Senate apportionment'], 'Grassroots mobilization activates members or supporters to communicate with policymakers and demonstrate organized public pressure.', { cognitiveProcess: 'identify' }),
  q(5, '5.7', '2.C', 'An interest group files an amicus brief in a case involving a policy that affects its members. What is the group trying to do?', 'Influence judicial reasoning by presenting legal or policy arguments relevant to the case.', ['Choose the next president through the Electoral College', 'Replace the parties in Congress with interest-group delegates', 'Prevent the Court from considering constitutional questions'], 'Amicus briefs let organizations provide information and arguments without becoming the principal party that brought the case.', { cognitiveProcess: 'connect' }),
  q(5, '5.8', '3.B', 'A candidate wins the national popular vote but receives fewer electoral votes than an opponent. Which conclusion is accurate?', 'The Electoral College allocates electoral votes through state-based rules rather than using a single national popular-vote total.', ['The result proves that electoral votes are assigned equally to every candidate.', 'The result means the House did not conduct an election.', 'The result shows that state election rules have no effect on presidential outcomes.'], 'The Electoral College is a state-based constitutional process, so the national popular vote and electoral-vote outcome can diverge.', { cognitiveProcess: 'explain' }),
  q(5, '5.9', '3.B', 'A graph shows that incumbents win 89 percent of races in safe districts but 55 percent in highly competitive districts. Which conclusion is best supported?', 'Incumbency is associated with an advantage, but district competitiveness also matters.', ['Incumbency guarantees victory in every district.', 'Competitive districts eliminate all incumbent resources.', 'The graph proves that campaign spending has no relationship to elections.'], 'The graph supports a conditional incumbency pattern and cautions against treating the advantage as a guarantee.', { cognitiveProcess: 'interpret', stimulus: 'Incumbent success is higher in safe districts than in highly competitive districts across the measured cycles.' }),
  q(5, '5.10', '5.A', 'A campaign hires consultants to coordinate polling, fundraising, digital communication, and field organizing. Which feature of modern campaigns is illustrated?', 'Professionalization and specialization of campaign operations', ['The replacement of elections with judicial appointments', 'The elimination of political parties from candidate recruitment', 'The transfer of campaign authority to state courts'], 'Modern campaigns often use specialized consultants, data operations, fundraising systems, and communication teams to coordinate strategy.', { cognitiveProcess: 'identify' }),
  q(5, '5.11', '4.D', 'An advertisement says it is paid for by an independent organization but provides little information about the organizations funders. Which evaluation is most important?', 'Consider how funding transparency and the organizations purpose may affect the source perspective and credibility.', ['Assume the message is neutral because the organization is independent.', 'Conclude that the advertisement is a judicial opinion.', 'Treat the advertisement as a government document because it discusses policy.'], 'Source analysis asks who created and funded a message, what audience it targets, what it wants the audience to do, and what evidence it supplies.', { cognitiveProcess: 'analyze', stimulus: 'The ad urges voters to contact legislators about a proposed bill but lists no individual donors.' }),
  q(5, '5.12', '1.D', 'A news organization repeatedly highlights immigration policy while giving little attention to other legislative issues. Which media function is most directly involved?', 'Agenda setting by influencing which issues receive sustained public attention.', ['Judicial review by declaring a policy unconstitutional', 'Cloture by ending debate in the Senate', 'Federalism by dividing authority between states'], 'Agenda setting concerns issue prominence and attention; it does not necessarily determine the direction of every citizens opinion.', { cognitiveProcess: 'identify' }),
  q(5, '5.13', '5.B', 'A social-media user shares an inaccurate political claim after seeing it repeated by several accounts in the same online network. Which risk is most relevant?', 'Repetition within a fragmented network can create perceived confirmation without establishing accuracy.', ['Repeated exposure guarantees that the claim is supported by evidence.', 'Digital media prevent all citizens from receiving political information.', 'The network has the constitutional power to certify election results.'], 'Changing media environments can increase speed and participation while also making source evaluation, correction, and cross-checking more important.', { cognitiveProcess: 'evaluate' }),
];
